+  for (const rule of css.matchAll(/([^{}]+)\{[^}]*max-width:\s*\d+(?:\.\d+)?ch/g)) {
+    assert.match(rule[1], /:has\(\.pricing-section-index\)/, rule[1].trim());
+  }
+});

